{{-- Inserts the docs components (same markup as the live guide) at the cursor of the textarea below it --}}
<div class="adm-doc-tools" role="toolbar" aria-label="Insert a docs component">
  <button type="button" data-snippet="paragraph" title="Paragraph"><i class="fa-solid fa-paragraph"></i>Text</button>
  <button type="button" data-snippet="list" title="Bullet list"><i class="fa-solid fa-list-ul"></i>List</button>
  <button type="button" data-snippet="steps" title="Numbered steps"><i class="fa-solid fa-list-ol"></i>Steps</button>
  <button type="button" data-snippet="tip" title="Tip box"><i class="fa-solid fa-lightbulb"></i>Tip</button>
  <button type="button" data-snippet="note" title="Note box"><i class="fa-solid fa-circle-info"></i>Note</button>
  <button type="button" data-snippet="warn" title="Warning box"><i class="fa-solid fa-triangle-exclamation"></i>Warning</button>
  <button type="button" data-snippet="screenshot" title="Upload a screenshot"><i class="fa-solid fa-image"></i>Screenshot</button>
  <button type="button" data-snippet="table" title="Table"><i class="fa-solid fa-table"></i>Table</button>
  <button type="button" data-snippet="shortcuts" title="Keyboard shortcut list"><i class="fa-solid fa-keyboard"></i>Shortcuts</button>
  <button type="button" data-snippet="kbd" title="A key, e.g. F2"><i class="fa-regular fa-keyboard"></i>Key</button>
  <button type="button" data-snippet="ui" title="A button or menu name"><i class="fa-solid fa-hand-pointer"></i>UI label</button>
  <button type="button" data-snippet="tab" title="A ribbon tab name"><i class="fa-solid fa-folder"></i>Tab</button>
</div>
